declare(strict_types=1);require dirname(__DIR__).'/bootstrap.php';header('Content-Type: application/json; charset=utf-8');$expected=(string)($config['SYNC_TOKEN']??'');$auth=(string)($_SERVER['HTTP_AUTHORIZATION']??'');if(strlen($expected)<32||!preg_match('/^Bearer\s+(.+)$/',$auth,$m)||!hash_equals($expected,$m[1])){http_response_code(401);exit(json_encode(['ok'=>false,'error'=>'unauthorized']));}
if($_SERVER['REQUEST_METHOD']==='GET'){$db->beginTransaction();$row=$db->query("SELECT d.id documento_id,d.tipo,a.id acuerdo_id,a.fecha_acuerdo,a.tipo_acuerdo,a.saldo_negociado deuda_total,a.monto_acordado,a.monto_inicial,c.nombre_completo,c.numero_documento dni,c.direccion,c.distrito,c.departamento,a.telefono_documento telefono,a.correo_documento correo,o.numero_operacion,o.producto FROM documentos d JOIN acuerdos a ON a.id=d.acuerdo_id JOIN clientes c ON c.id=a.cliente_id JOIN operaciones o ON o.id=a.operacion_id WHERE d.estado='PENDIENTE' OR (d.estado='GENERANDO' AND d.updated_at<DATE_SUB(NOW(),INTERVAL 15 MINUTE)) ORDER BY d.id LIMIT 1 FOR UPDATE")->fetch();if(!$row){$db->commit();exit(json_encode(['ok'=>true,'job'=>null]));}$db->prepare("UPDATE documentos SET estado='GENERANDO' WHERE id=?")->execute([$row['documento_id']]);$q=$db->prepare('SELECT numero_cuota,fecha_vencimiento fecha,monto FROM cuotas WHERE acuerdo_id=? ORDER BY numero_cuota');$q->execute([$row['acuerdo_id']]);$row['cuotas']=$q->fetchAll();$db->commit();exit(json_encode(['ok'=>true,'job'=>$row],JSON_UNESCAPED_UNICODE));}
if($_SERVER['REQUEST_METHOD']==='POST'){$input=json_decode((string)file_get_contents('php://input'),true);$id=(int)($input['documento_id']??0);$binary=base64_decode((string)($input['pdf_base64']??''),true);if(!$id||$binary===false||strlen($binary)>8*1024*1024||substr($binary,0,5)!=='%PDF-'){http_response_code(422);exit(json_encode(['ok'=>false,'error'=>'invalid_pdf']));}$base=(string)($config['DOCUMENT_OUTPUT_PATH']??'');if($base===''||(!is_dir($base)&&!mkdir($base,0700,true))){http_response_code(503);exit(json_encode(['ok'=>false,'error'=>'storage_unavailable']));}$key=bin2hex(random_bytes(24)).'.pdf';if(file_put_contents(rtrim($base,'/\\').DIRECTORY_SEPARATOR.$key,$binary,LOCK_EX)===false){http_response_code(500);exit(json_encode(['ok'=>false,'error'=>'write_failed']));}$q=$db->prepare("UPDATE documentos SET estado='DISPONIBLE',storage_key=?,generado_at=NOW() WHERE id=? AND estado='GENERANDO'");$q->execute([$key,$id]);exit(json_encode(['ok'=>true]));}http_response_code(405);echo json_encode(['ok'=>false]);
